class Solution:
    def closestValue(self, root, target: float) -> int:
        closest = root.val
        while root:
            if abs(root.val - target) < abs(closest - target) or \
               (abs(root.val - target) == abs(closest - target) and root.val < closest):
                closest = root.val
            root = root.left if target < root.val else root.right
        return closest

